TRAFFIC_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Personal CIC // Traffic</title>
<style>
:root{color-scheme:dark;--bg:#080c10;--panel:#0f151b;--panel2:#121b22;--line:#25323d;--text:#e7edf2;--muted:#8da0af;--good:#74d99f;--warn:#e8c56d;--bad:#ef7e7e;--accent:#79b8ff;--crowd:#c99cff;--city:#79d4c5;--cmpd:#f0ad79}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}header{position:sticky;top:0;z-index:20;background:rgba(8,12,16,.97);border-bottom:1px solid var(--line)}.brand{display:flex;align-items:baseline;gap:14px;padding:14px 18px 8px}.brand h1{font-size:18px;letter-spacing:.12em;margin:0}.chip{font-size:10px;padding:2px 7px;border:1px solid var(--line);border-radius:999px;color:var(--muted)}nav{display:flex;gap:8px;padding:0 18px 10px}nav a{color:var(--muted);text-decoration:none;border:1px solid var(--line);padding:5px 8px;border-radius:4px;font-size:11px}.active{color:var(--text)!important;border-color:#466174!important;background:#111b23}.status-strip{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px;padding:10px 18px}.status,.panel{border:1px solid var(--line);background:var(--panel);border-radius:6px}.status{padding:8px 10px}.label{font-size:9px;letter-spacing:.1em;color:var(--muted)}.value{font-size:14px;margin-top:4px}.current,.nominal{color:var(--good)}.degraded{color:var(--warn)}.unavailable{color:var(--bad)}main{padding:0 18px 22px}.layout{display:grid;grid-template-columns:minmax(0,2.4fr) minmax(290px,.8fr);gap:10px}.panel h2{margin:0;padding:9px 11px;border-bottom:1px solid var(--line);background:var(--panel2);font-size:11px;letter-spacing:.08em}.map-tools{display:flex;gap:6px;flex-wrap:wrap;padding:8px 10px;border-bottom:1px solid var(--line)}button{font:inherit;font-size:10px;color:var(--text);background:#111a21;border:1px solid var(--line);border-radius:4px;padding:5px 7px;cursor:pointer}button:hover{border-color:#466174}.layers{display:flex;gap:10px;flex-wrap:wrap;margin-left:auto}.layers label{font-size:10px;color:var(--muted);display:flex;gap:4px;align-items:center}.map-wrap{position:relative;overflow:hidden;background:#080d11;min-height:560px}.map-wrap svg{display:block;width:100%;height:560px;touch-action:none;cursor:grab}.map-wrap svg.dragging{cursor:grabbing}.map-note{position:absolute;left:9px;bottom:7px;background:rgba(8,12,16,.82);border:1px solid var(--line);padding:5px 7px;font-size:9px;color:var(--muted);max-width:70%}.side{display:flex;flex-direction:column;gap:10px}.source-list,.gap-list,.event-list,.detail{padding:8px 10px}.source{padding:6px 0;border-bottom:1px solid #1b2730}.source:last-child{border-bottom:0}.source-head{display:flex;justify-content:space-between;gap:8px;font-size:10px}.source-sub{font-size:9px;color:var(--muted);margin-top:3px;line-height:1.4}.gap{font-size:9px;color:var(--warn);padding:5px 0;border-bottom:1px solid #1b2730;line-height:1.45}.detail{font-size:10px;line-height:1.5;min-height:112px;overflow-wrap:anywhere}.detail strong{color:var(--accent)}.event-list{max-height:310px;overflow:auto}.event-row{font-size:9px;padding:6px 0;border-bottom:1px solid #1b2730;cursor:pointer}.event-row:hover{color:var(--accent)}.event-row .meta{color:var(--muted);margin-top:2px}.legend{display:flex;gap:9px;flex-wrap:wrap;padding:7px 10px;border-top:1px solid var(--line);font-size:9px;color:var(--muted)}.sw{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:3px}.external{margin-top:10px}.external-body{padding:10px}.external iframe{width:100%;height:520px;border:1px solid var(--line);border-radius:4px;background:#0a1015}.disclosure{font-size:9px;color:var(--warn);line-height:1.5;margin-bottom:8px}.foot{font-size:9px;color:var(--muted);padding:8px 18px 20px}.roads{fill:none;stroke:#263640;stroke-width:1.1;vector-effect:non-scaling-stroke}.secondary{stroke:#18242c;stroke-width:.55}.county{fill:none;stroke:#3a4d59;stroke-width:1;vector-effect:non-scaling-stroke}.place{fill:#708391;font-size:10px}.evt{fill:#ef7e7e;stroke:#0a0e12;stroke-width:1.5;vector-effect:non-scaling-stroke;cursor:pointer}.evt-wzdx{fill:#e8c56d}.evt-cmpd{fill:var(--cmpd)}.evt-city{fill:var(--city)}.camera{fill:#79b8ff;stroke:#0a0e12;stroke-width:1.2;cursor:pointer}.sign{fill:#e8c56d;stroke:#0a0e12;stroke-width:1.2;cursor:pointer}.home{fill:#fff;stroke:#79b8ff;stroke-width:2;vector-effect:non-scaling-stroke}.event-line{fill:none;stroke:#ef7e7e;stroke-width:2;vector-effect:non-scaling-stroke;opacity:.75}.line-wzdx{stroke:#e8c56d}.line-city{stroke:var(--city)}@media(max-width:1000px){.layout{grid-template-columns:1fr}.status-strip{grid-template-columns:repeat(2,minmax(0,1fr))}.map-wrap,.map-wrap svg{min-height:460px;height:460px}}
</style>
</head>
<body>
<header><div class="brand"><h1>PERSONAL CIC // TRAFFIC</h1><span class="chip">READ-ONLY</span><span class="chip">003f RC1</span></div><nav><a href="/systems">SYSTEMS</a><a href="/world">WORLD</a><a class="active" href="/traffic">TRAFFIC</a></nav></header>
<section class="status-strip">
<div class="status"><div class="label">TRAFFIC PICTURE</div><div id="picture" class="value unavailable">--</div></div>
<div class="status"><div class="label">EVENT KERNELS</div><div id="kernels" class="value">--</div></div>
<div class="status"><div class="label">CAMERAS</div><div id="cams" class="value">--</div></div>
<div class="status"><div class="label">ACTIVE SIGNS</div><div id="signs" class="value">--</div></div>
<div class="status"><div class="label">API</div><div id="api" class="value unavailable">CONNECTING</div></div>
</section>
<main>
<div class="layout">
<section class="panel">
<h2>LOCAL MOBILITY PICTURE // SOURCE-PRESERVING MAP</h2>
<div class="map-tools"><button id="reset" type="button">RESET VIEW</button><button id="zoom-in" type="button">ZOOM +</button><button id="zoom-out" type="button">ZOOM −</button><div class="layers">
<label><input id="l-events" type="checkbox" checked> NCDOT EVENTS</label>
<label><input id="l-wzdx" type="checkbox" checked> WZDx</label>
<label><input id="l-city" type="checkbox" checked> CITY</label>
<label><input id="l-cmpd" type="checkbox" checked> CMPD</label>
<label><input id="l-cameras" type="checkbox" checked> CAMERAS</label>
<label><input id="l-signs" type="checkbox" checked> SIGNS</label>
<label><input id="l-lastknown" type="checkbox"> LAST-KNOWN</label>
</div></div>
<div class="map-wrap"><svg id="map" viewBox="0 0 1200 760" role="img" aria-label="Interactive local traffic situation map"></svg><div id="map-note" class="map-note">Awaiting local map context.</div></div>
<div class="legend"><span><i class="sw" style="background:#ef7e7e"></i>NCDOT event</span><span><i class="sw" style="background:#e8c56d"></i>WZDx work zone / sign</span><span><i class="sw" style="background:#79d4c5"></i>Charlotte closure</span><span><i class="sw" style="background:#f0ad79"></i>CMPD CAD (list until geocoded)</span><span><i class="sw" style="background:#79b8ff"></i>camera</span></div>
</section>
<div class="side">
<section class="panel"><h2>COLLECTION // SOURCE HEALTH</h2><div id="sources" class="source-list"></div></section>
<section class="panel"><h2>SELECTED EVIDENCE</h2><div id="detail" class="detail">Select a mapped object or source event. Source identity is preserved; event kernels do not erase underlying observations.</div></section>
<section class="panel"><h2>EVENT OBSERVATIONS</h2><div id="event-list" class="event-list"></div></section>
<section class="panel"><h2>COLLECTION GAPS</h2><div id="gaps" class="gap-list"></div></section>
</div>
</div>
<section class="panel external"><h2>WAZE // EXTERNAL CROWD VISUAL</h2><div class="external-body"><div id="waze-disclosure" class="disclosure">Not loaded. This is intentionally outside canonical CIC WorldState until a supported machine-readable crowd feed is available. Loading it creates direct browser egress to Waze.</div><button id="load-waze" type="button">LOAD WAZE LIVE MAP</button><div id="waze-holder" style="margin-top:8px"></div></div></section>
</main>
<div class="foot">CIC map objects are projections of locally held WorldState. Waze is separately labeled operator-opt-in external visual evidence and is never counted as normalized corroboration in RC1. <span id="generated"></span></div>
<script>
const $=id=>document.getElementById(id);const NS='http://www.w3.org/2000/svg';let data=null,context=null;let bounds=null;let baseView=[0,0,1200,760],view=[...baseView];
function state(el,v){v=String(v||'unavailable').toLowerCase();el.textContent=v.toUpperCase();el.className='value '+v}
function age(v){return Number.isFinite(v)?Math.round(v)+'s':'--'}
function node(tag,attrs={}){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,String(v));return e}
function setView(){ $('map').setAttribute('viewBox',view.join(' ')) }
function project(lon,lat){if(!bounds)return null;const [w,s,e,n]=bounds;if(!(lon>=w&&lon<=e&&lat>=s&&lat<=n))return null;return[(lon-w)/(e-w)*1200,(n-lat)/(n-s)*760]}
function geometryPoints(g){return(g||[]).map(p=>project(Number(p.longitude),Number(p.latitude))).filter(Boolean)}
function linePath(points){return points.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ')}
function drawGeo(group,geometry,klass){if(!geometry)return;const kind=geometry.type,c=geometry.coordinates;const path=(pairs)=>{const pts=(pairs||[]).map(p=>project(Number(p[0]),Number(p[1]))).filter(Boolean);if(pts.length>1)group.appendChild(node('path',{d:linePath(pts),class:klass}))};if(kind==='LineString')path(c);else if(kind==='MultiLineString')for(const l of c||[])path(l);else if(kind==='Polygon')for(const r of c||[])path(r);else if(kind==='MultiPolygon')for(const p of c||[])for(const r of p||[])path(r)}
function clearMap(){const svg=$('map');while(svg.firstChild)svg.removeChild(svg.firstChild)}
function detail(title,items){const el=$('detail');el.replaceChildren();const h=document.createElement('div');const strong=document.createElement('strong');strong.textContent=String(title);h.appendChild(strong);el.appendChild(h);for(const [k,v] of items){if(v===null||v===undefined||v==='')continue;const d=document.createElement('div');d.textContent=k+': '+(Array.isArray(v)?v.join(' // '):v);el.appendChild(d)}}
function visibleSource(e){if(e.source_authoritative_now)return true;return $('l-lastknown').checked}
function draw(){clearMap();if(!data)return;const svg=$('map');const bg=node('g');svg.appendChild(bg);if(context&&bounds){for(const f of context.counties||[])drawGeo(bg,f.geometry,'county');for(const f of context.secondary_roads||[])drawGeo(bg,f.geometry,'roads secondary');for(const f of context.primary_roads||[])drawGeo(bg,f.geometry,'roads');for(const p of context.places||[]){const q=project(Number(p.lon),Number(p.lat));if(!q)continue;const t=node('text',{x:q[0]+3,y:q[1]-3,class:'place'});t.textContent=p.name||'';bg.appendChild(t)}}
const home=project(Number(data.location.longitude),Number(data.location.latitude));if(home)svg.appendChild(node('circle',{cx:home[0],cy:home[1],r:5,class:'home'}));
for(const e of data.events||[]){if(!visibleSource(e))continue;const key=e.source_key;if(key==='drivenc_events'&&!$('l-events').checked)continue;if(key==='wzdx'&&!$('l-wzdx').checked)continue;if(key==='charlotte_closures'&&!$('l-city').checked)continue;if(key==='cmpd'&&!$('l-cmpd').checked)continue;const pts=geometryPoints(e.geometry);if(pts.length>1){const klass='event-line '+(key==='wzdx'?'line-wzdx':key==='charlotte_closures'?'line-city':'');const p=node('path',{d:linePath(pts),class:klass});p.addEventListener('click',()=>showEvent(e));svg.appendChild(p)}if(pts.length){const p=pts[0];const klass='evt '+(key==='wzdx'?'evt-wzdx':key==='charlotte_closures'?'evt-city':key==='cmpd'?'evt-cmpd':'');const c=node('circle',{cx:p[0],cy:p[1],r:5,class:klass});c.addEventListener('click',()=>showEvent(e));svg.appendChild(c)}}
if($('l-cameras').checked){for(const c of data.cameras?.cameras||[]){if(!data.cameras.authoritative_now&&!$('l-lastknown').checked)continue;const p=project(Number(c.longitude),Number(c.latitude));if(!p)continue;const n=node('circle',{cx:p[0],cy:p[1],r:3.2,class:'camera'});n.addEventListener('click',()=>detail('CAMERA '+c.camera_id,[['source',c.source_family],['road',c.roadway],['direction',c.direction],['location',c.location],['status',c.status],['video',c.video_url||'not exposed']]));svg.appendChild(n)}}
if($('l-signs').checked){for(const s of data.message_signs?.signs||[]){if(!data.message_signs.authoritative_now&&!$('l-lastknown').checked)continue;const p=project(Number(s.longitude),Number(s.latitude));if(!p)continue;const n=node('rect',{x:p[0]-3,y:p[1]-3,width:6,height:6,class:'sign'});n.addEventListener('click',()=>detail('MESSAGE SIGN '+s.sign_id,[['source',s.source_family],['road',s.roadway],['updated',s.updated_at],['messages',s.messages]]));svg.appendChild(n)}}
}
function showEvent(e){detail((e.event_type||'EVENT').toUpperCase(),[['source family',e.source_family],['provider',e.provider],['class',e.collection_class],['source state',e.source_availability],['record id',e.source_record_id],['upstream id',e.upstream_event_id],['road',e.roadway],['direction',e.direction],['county',e.county],['description',e.description],['severity',e.severity],['full closure',e.full_closure],['lanes',e.lanes_affected],['reported',e.reported_at],['updated',e.updated_at]])}
function sourceRow(name,s){const d=document.createElement('div');d.className='source';const o=s?.observation||{};const head=document.createElement('div');head.className='source-head';const a=document.createElement('span');a.textContent=name;const b=document.createElement('span');b.textContent=String(o.availability||'unavailable').toUpperCase();b.className=String(o.availability||'unavailable').toLowerCase();head.append(a,b);const sub=document.createElement('div');sub.className='source-sub';sub.textContent=(s?.provider||'--')+' // local '+(s?.local_record_count??'--')+' / source '+(s?.source_record_count??'--')+' // success age '+age(o.last_success_age_seconds)+(o.reasons?.length?' // '+o.reasons.join(' // '):'');d.append(head,sub);return d}
function populate(){const s=$('sources');s.replaceChildren();const es=data.event_sources||{};s.append(sourceRow('DRIVENC EVENTS',es.drivenc_events),sourceRow('WZDX WORK ZONES',es.wzdx),sourceRow('CMPD CAD',es.cmpd),sourceRow('CHARLOTTE CLOSURES',es.charlotte_closures),sourceRow('DRIVENC CAMERAS',data.cameras),sourceRow('MESSAGE SIGNS',data.message_signs));const gaps=$('gaps');gaps.replaceChildren();for(const g of data.summary?.collection_gaps||[]){const x=document.createElement('div');x.className='gap';x.textContent=g;gaps.appendChild(x)}const list=$('event-list');list.replaceChildren();for(const e of (data.events||[]).slice().sort((a,b)=>String(b.updated_at||b.reported_at||'').localeCompare(String(a.updated_at||a.reported_at||''))).slice(0,120)){const r=document.createElement('div');r.className='event-row';r.textContent=(e.roadway||e.event_type||'event')+' // '+(e.description||'');const m=document.createElement('div');m.className='meta';m.textContent=e.source_family+' // '+e.source_availability.toUpperCase();r.appendChild(m);r.addEventListener('click',()=>showEvent(e));list.appendChild(r)}}
async function refresh(){try{const r=await fetch('/api/v1/traffic',{cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);data=await r.json();$('api').textContent='LIVE';$('api').className='value current';state($('picture'),data.summary?.availability);$('kernels').textContent=data.summary?.event_kernels??'--';$('cams').textContent=data.summary?.cameras??'--';$('signs').textContent=data.summary?.active_message_signs??'--';$('generated').textContent=' // served '+data.presentation.generated_at;const mc=data.map_context||{};if(mc.context_url){try{const cr=await fetch(mc.context_url,{cache:'no-store'});if(cr.ok)context=await cr.json()}catch(_e){context=null}}if(context?.bounds){bounds=[context.bounds.west,context.bounds.south,context.bounds.east,context.bounds.north];$('map-note').textContent='TIGERweb reference context // '+mc.context_state+' // '+(data.location.radius_miles??'--')+' mi traffic scope'}else if(Number.isFinite(data.location.latitude)&&Number.isFinite(data.location.longitude)&&Number.isFinite(data.location.radius_miles)){const lat=data.location.latitude,lon=data.location.longitude,dlat=data.location.radius_miles/69,dlon=data.location.radius_miles/(69*Math.cos(lat*Math.PI/180));bounds=[lon-dlon,lat-dlat,lon+dlon,lat+dlat];$('map-note').textContent='No local TIGERweb context artifact; traffic geometry only'}populate();draw()}catch(err){$('api').textContent='UNAVAILABLE';$('api').className='value unavailable';$('map-note').textContent=String(err)}}
for(const id of ['l-events','l-wzdx','l-city','l-cmpd','l-cameras','l-signs','l-lastknown'])$(id).addEventListener('change',draw);$('reset').addEventListener('click',()=>{view=[...baseView];setView()});function zoom(f){const[cx,cy]=[view[0]+view[2]/2,view[1]+view[3]/2];view[2]*=f;view[3]*=f;view[0]=cx-view[2]/2;view[1]=cy-view[3]/2;setView()}$('zoom-in').addEventListener('click',()=>zoom(.8));$('zoom-out').addEventListener('click',()=>zoom(1.25));$('map').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:.89)},{passive:false});let drag=null;$('map').addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY,...view];$('map').setPointerCapture(e.pointerId);$('map').classList.add('dragging')});$('map').addEventListener('pointermove',e=>{if(!drag)return;const rect=$('map').getBoundingClientRect();view[0]=drag[2]-(e.clientX-drag[0])*drag[4]/rect.width;view[1]=drag[3]-(e.clientY-drag[1])*drag[5]/rect.height;setView()});$('map').addEventListener('pointerup',()=>{drag=null;$('map').classList.remove('dragging')});$('load-waze').addEventListener('click',()=>{const w=data?.external_visual_sources?.waze;if(!w?.enabled||!w.url){$('waze-disclosure').textContent='Waze external visual source is unavailable in the current traffic projection.';return}const f=document.createElement('iframe');f.src=w.url;f.title='Waze Live Map external crowd traffic view';f.referrerPolicy='strict-origin-when-cross-origin';$('waze-holder').replaceChildren(f);$('waze-disclosure').textContent=w.disclosure});refresh();setInterval(refresh,15000);
</script>
</body>
</html>'''
